const rayvn_config = global.get('rayvn_config')
const url = global.get('rayvn_url')
const path = `/logs/${rayvn_config.log_id}/entries`

msg.headers = {
    "Authorization": "Bearer " + rayvn_config.api_key
};

msg.url = url + path;

return msg;

let rayvn_config = global.get('rayvn_config');

if (!rayvn_config.api_key || !rayvn_config.log_id) {
    node.error('rayvn not configured. cannot poll rayvn');
    return null;
}

return msg;
